"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[6562],{28453:(n,t,h)=>{h.d(t,{R:()=>m,x:()=>e});var i=h(96540);const c={},g=i.createContext(c);function m(n){const t=i.useContext(g);return i.useMemo(function(){return"function"==typeof n?n(t):{...t,...n}},[t,n])}function e(n){let t;return t=n.disableParentContext?"function"==typeof n.components?n.components(c):n.components||c:m(n.components),i.createElement(g.Provider,{value:t},n.children)}},55751:n=>{n.exports=JSON.parse('{"permalink":"/blog/cuoc-doi-mong-uoc","source":"@site/blog/20260224-cuoc-doi-mong-uoc.md","title":"Cu\u1ed9c \u0111\u1eddi mong \u01b0\u1edbc","description":"H\xf4m nay, m\xecnh l\xean c\xf4ng ty v\xec CEO sang th\u0103m \u0111\u1ea7u n\u0103m m\u1edbi. L\xe2u qu\xe1 tr\u1eddi m\u1edbi l\xean c\xf4ng ty, nhi\u1ec1u ng\u01b0\u1eddi c\xf2n t\u01b0\u1edfng m\xecnh l\xe0 nh\xe2n vi\xean m\u1edbi.","date":"2026-02-24T00:00:00.000Z","tags":[{"inline":false,"label":"Spirit","permalink":"/blog/tags/spirit","description":"Spirituality and inner exploration"}],"readingTime":3.99,"hasTruncateMarker":true,"authors":[{"name":"Khanh Ha","title":"cat-server/ex-da","page":{"permalink":"/blog/authors/khanh-ha"},"imageURL":"https://github.com/khanhhabmt/blog-media/releases/download/media-assets/bach.jpg","key":"khanh-ha"}],"frontMatter":{"slug":"cuoc-doi-mong-uoc","title":"Cu\u1ed9c \u0111\u1eddi mong \u01b0\u1edbc","authors":["khanh-ha"],"tags":["spirit"],"date":"2026-02-24T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"Kh\xf4ng l\xe0m g\xec","permalink":"/blog/khong-lam-gi-cover-2020"},"nextItem":{"title":"Kem cafe","permalink":"/blog/kem-cafe"}}')},84542:(n,t,h)=>{h.r(t),h.d(t,{assets:()=>a,contentTitle:()=>e,default:()=>l,frontMatter:()=>m,metadata:()=>i,toc:()=>o});var i=h(55751),c=h(74848),g=h(28453);const m={slug:"cuoc-doi-mong-uoc",title:"Cu\u1ed9c \u0111\u1eddi mong \u01b0\u1edbc",authors:["khanh-ha"],tags:["spirit"],date:new Date("2026-02-24T00:00:00.000Z")},e=void 0,a={authorsImageUrls:[void 0]},o=[];function r(n){const t={br:"br",hr:"hr",p:"p",...(0,g.R)(),...n.components};return(0,c.jsxs)(c.Fragment,{children:[(0,c.jsxs)(t.p,{children:["H\xf4m nay, m\xecnh l\xean c\xf4ng ty v\xec CEO sang th\u0103m \u0111\u1ea7u n\u0103m m\u1edbi. L\xe2u qu\xe1 tr\u1eddi m\u1edbi l\xean c\xf4ng ty, nhi\u1ec1u ng\u01b0\u1eddi c\xf2n t\u01b0\u1edfng m\xecnh l\xe0 nh\xe2n vi\xean m\u1edbi.",(0,c.jsx)(t.br,{}),"\n","N\xf3i v\u1ec1 vi\u1ec7c m\xecnh s\u1eafp part-time v\xe0 officially remote (xin th\xfa t\u1ed9i l\xe0 5 th\xe1ng nay m\xecnh remote l\u1eadu), m\u1ecdi ng\u01b0\u1eddi h\u1ecfi th\u1ebf ch\u1ecb l\u1ea1i v\u1ec1 qu\xea \xe0. M\xecnh b\u1ea3o, t c\u0169ng ch\u01b0a bi\u1ebft, ch\u1eafc t nay \u0111\xe2y mai \u0111\xf3 :))."]}),"\n",(0,c.jsx)(t.hr,{}),"\n",(0,c.jsx)(t.p,{children:"M\xecnh b\u1ecb tin l\xe0 nh\u1eefng c\xe1i m\xecnh n\xf3i ra v\xe0 th\u1ef1c s\u1ef1 mu\u1ed1n n\xf3 \u0111\u1ec1u th\xe0nh th\u1eadt. Ho\u1eb7c l\xe0 khi n\xf3 th\xe0nh th\u1eadt m\xecnh nh\u1edb l\u1ea1i c\xe1i l\xfac \u0111\xe3 n\xf3i, c\xf2n c\xe1i kh\xf4ng th\xe0nh n\xf3 ko c\xf3 trigger l\u1ea1i l\xfac m\xecnh n\xf3i (n\u1ebfu c\xf3) n\xean m\xecnh ko c\xf3 th\u1ed1ng k\xea :))."}),"\n",(0,c.jsx)(t.p,{children:'Ng\xe0y x\u01b0a, l\xfac m\u1edbi \u0111i l\xe0m, m\xecnh l\xe0m nh\xe2n vi\xean t\xedn d\u1ee5ng doanh nghi\u1ec7p \u1edf ng\xe2n h\xe0ng. Ph\xf2ng l\xe0m vi\u1ec7c k\xedn m\xedt, kh\xf4ng c\u1eeda s\u1ed5, \u0111\xe8n v\xe0 \u0111i\u1ec1u ho\xe0 b\u1eadt 24/7 (x\u1ea1o, m\xe0 nghe n\xf3 tr\xf4i, n\xean th\xf4i). M\xecnh gh\xe9t c\xe1i c\u1ea3nh m\u1eb7c \u0111\u1ed3 c\xf4ng s\u1edf \u0111i gi\xe0y cao g\xf3t (d\xf9 m\xecnh ch\u1ec9 mang c\xf3 m\u1ed7i 5cm) ng\u1ed3i trong c\xe1i ph\xf2ng \u0111\u1ea5y d\xe3 c\u1ea3 man. \u0110i l\xe0m \u0111\u01b0\u1ee3c 3 th\xe1ng, ng\xe0y n\xe0o ng\u1ee7 d\u1eady c\u0169ng t\u1ef1 h\u1ecfi: "L\xe0m \u0111\u01b0\u1ee3c t\u1edbi n\u0103m 55 tu\u1ed5i kh\xf4ng h\u1ea3 H\xe0?" (h\u1ed3i \u0111\xf3 m\xe0 bi\u1ebft tu\u1ed5i h\u01b0u sau n\xe0y t\u0103ng th\xec ch\u1eafc l\xe0 n\u1ed9p \u0111\u01a1n ngh\u1ec9 vi\u1ec7c ngay :))).'}),"\n",(0,c.jsx)(t.p,{children:"Th\xf4i th\xec d\xf9 sao c\u0169ng l\xe0 c\xf4ng vi\u1ec7c \u0111\u1ea7u ti\xean, l\xfac \u0111\xf3 \u0111ang s\u1ed1ng c\xf9ng v\u1edbi b\u1ed1 m\u1eb9, b\u1ecb t\xe1c \u0111\u1ed9ng kh\xf4ng \xedt n\xean d\xe2y d\u01b0a \u0111\u01b0\u1ee3c th\xeam 5 th\xe1ng n\u1eefa th\xec m\u1edbi quy\u1ebft t\xe2m bu\xf4ng b\u1ecf, a di \u0111\xe0 ph\u1eadt."}),"\n",(0,c.jsx)(t.p,{children:"L\xfac \u0111\xf3 c\u0169ng ch\u1ea3 bi\u1ebft m\xecnh s\u1ebd l\xe0m g\xec ti\u1ebfp, x\xe1ch ba l\xf4 quay l\u1ea1i S\xe0i G\xf2n, s\u1ed1ng c\xf9ng ng\u01b0\u1eddi b\u1ea1n m\xe0 n\u0103m nay s\u1ebd l\xe0 co-founder/investor start-up c\u1ee7a m\xecnh. Cu\u1ed9c \u0111\u1eddi n\xf3 c\u1ee9 tr\xf2n xoe nh\u01b0 th\u1ebf."}),"\n",(0,c.jsx)(t.p,{children:'M\xecnh \u0111\xe3 t\u1eebng tuy\u1ec7t v\u1ecdng apply c\xe1c lo\u1ea1i job m\xe0 m\xecnh ngh\u0129 l\xe0 "ph\xf9 h\u1ee3p", nh\u01b0ng n\xf3 kh\xf4ng \u0111\u1eadu :)).'}),"\n",(0,c.jsx)(t.p,{children:"Xong th\u1eb1ng Hi\u1ebfu n\xf3 b\u1ea3o m\xecnh \u0111i h\u1ecdc Master \u0111i. C\xe1i th\u1eb1ng n\xe0y ph\xe1n th\u1ebf m\xe0 l\u1ea1i hay. H\u1ecdc Master \u0111\xfang l\xe0 c\u1ee9u r\u1ed7i cho nh\u1eefng th\xe0nh ph\u1ea7n qu\xe1i g\u1edf th\u1ea5t nghi\u1ec7p x\xe3 h\u1ed9i ch\xea nh\u01b0 m\xecnh."}),"\n",(0,c.jsx)(t.p,{children:"H\u1ecdc xong ch\u01b0\u01a1ng tr\xecnh \u0111i t\u1eaft \u0111\xf3n \u0111\u1ea7u th\u1ecb tr\u01b0\u1eddng ch\u1ee9ng kho\xe1n ph\xe1i sinh, m\xe0 t\u1edbi 11 n\u0103m sau khi t\u1ed1t nghi\u1ec7p VN m\u1edbi manh nha c\xf3 ch\u1ee9ng kho\xe1n ph\xe1i sinh. \u0110\u1ed9 n\xe0y th\xec t\u1ef1 d\u01b0ng c\xf3 \xf4ng th\u1ea7y \u0111ang ch\u1ebft d\xed trong c\xe1i job \u1edf c\xf4ng ty, m\u1edbi g\xe0i m\xecnh v\xe0o h\u1ed1t shit \u0111\u1ec3 \u1ed5ng nh\u1ea3y. Gi\u1edd m\xecnh nh\xecn l\u1ea1i th\xec th\u1ea5y th\u1ebf, ch\u1ee9 l\xfac \u0111\u1ea5y bi\u1ebft \u01a1n th\u1ea7y qu\xe1 tr\u1eddi. C\u0169ng kh\xf4ng ph\u1ea3i title Data Analyst g\xec, th\u1eddi \u0111\u1ea5y th\u1ec1 trong \u0111\u1ea7u m\xecnh hay th\u1eadm ch\xed tr\xean th\u1ecb tr\u01b0\u1eddng m\xecnh c\u0169ng kh\xf4ng c\xf3 nh\xecn th\u1ea5y c\xe1i job n\xe0o t\xean nh\u01b0 th\u1ebf. M\xecnh v\xe0o ch\u1eedi s\u1ebfp \u0111\xe1nh \u0111\u1ed3ng nghi\u1ec7p \u0111\u01b0\u1ee3c h\u01a1n n\u0103m th\xec c\u0169ng xin ngh\u1ec9. S\u1ebfp h\u1ecfi ngh\u1ec9 t\xednh l\xe0m g\xec th\u1ebf? M\xecnh b\u1ea3o em mu\u1ed1n l\xe0m Data chuy\xean s\xe2u h\u01a1n (c\u0169ng h\u01a1i v\xf5 m\u1ed3m cho m\u1ed9t l\xfd do). S\u1ebfp b\u1ea3o \u1edd \u1edd, c\u0169ng ch\u01b0a bi\u1ebft l\u1eafm c\xe1i \xfd em l\xe0 sao, t\u1ea1m bi\u1ec7t em. C\u0169ng \xf4ng s\u1ebfp n\xe0y, sau \u1ed5ng l\xe0m m\u1ed9t c\xe1i product v\u1ec1 CDP c\xf3 g\u1ecdi m\xecnh ra n\xf3i chuy\u1ec7n, khen m\xecnh mindset t\u1ed1t nh\xecn xa tr\xf4ng g\u1ea7n c\xe1c th\u1ee9 :)). Anh c\xf3 \u0111\u1ecdc \u0111\u01b0\u1ee3c th\xec anh c\u1ee9 c\u01b0\u1eddi cho em."}),"\n",(0,c.jsx)(t.p,{children:"D\xe1m b\u1ea3o kh\xf4ng thi\xeang kh\xf4ng, s\xe1ng m\u1edbi vi\u1ebft email ngh\u1ec9, chi\u1ec1u anh Tuy\xean TS g\u1ecdi h\u1ecfi em c\xf3 v\xe0o l\xe0m report gi\xf9m anh c\xe1i \u0111\u01b0\u1ee3c kh\xf4ng? Sau n\xe0y ng\u1eabm l\u1ea1i m\u1edbi th\u1ea5y, task l\xe0m report l\xe0 vi\u1ec7c m\xe0 c\xe1c \xf4ng anh kh\xf4ng ai mu\u1ed1n d\xednh v\xe0o, m\xe0 kh\xf4ng l\xe0m th\xec kh\xf4ng \u0111\u01b0\u1ee3c, c\xe1c \xf4ng c\xf2n \u0111ang m\xea model v\u1edbi feature engineering c\xe1c th\u1ee9. C\xf2n m\xecnh th\xec t\u1ef1 d\u01b0ng nh\u1edd kh\u1ea3 n\u0103ng bi\u1ebft code R d\u1ecdn r\xe1c l\xe0m report m\xe0 \u0111\u01b0\u1ee3c v\xe0o l\xe0m v\u1edbi m\u1ed9t team to\xe0n si\xeau nh\xe2n, th\u1eadt l\xe0 c\xf3 m\u01a1 c\u0169ng kh\xf4ng m\u01a1 ra \u0111\u01b0\u1ee3c gi\u1ea5c m\u01a1 n\xe0y."}),"\n",(0,c.jsx)(t.p,{children:"Trong h\u01a1n n\u0103m tr\u1eddi ch\u1eb7t ch\xe9m h\u1ed1t r\xe1c \u1edf \u0111\u1ea5y, \u0111\xe3 tr\xfang \u0111\u01b0\u1ee3c kh\xf4ng \xedt gi\xf3, k\u1ebft \u0111\u01b0\u1ee3c kh\xf4ng \xedt b\u1ea1n. M\u1edbi \u0111\xf3 \u0111\xe3 ch\u1ee5c n\u0103m r\u1ed3i, OMG."}),"\n",(0,c.jsx)(t.p,{children:"\xd4i c\xe1i \u0111\u1ec7ch, qu\xean m\u1ea5t, \u0111ang n\xf3i v\u1ee5 remote work. H\u1ed3i l\xe0m \u1edf c\xe1i ch\u1ed7 ch\u01b0a bi\u1ebft ngh\u1ec1 Data Analyst c\xf3 c\xe1i t\xean \u1ea5y, m\xecnh nghe c\xe1c b\xe1c chuy\xean gia c\u1ee7a c\xf4ng ty, s\u1ed1ng b\xean Nh\u1eadt, l\xe0m t\u01b0 v\u1ea5n part-time cho b\xean n\xe0y. Xong m\xecnh m\u1edbi b\u1ea3o, em mu\u1ed1n sau n\xe0y em c\u0169ng th\u1ebf, s\u1ed1ng \u1edf ch\u1ed7 em mu\u1ed1n, l\xe0m vi\u1ec7c ki\u1ebfm ti\u1ec1n v\xe0i ng\xe0y m\u1ed9t tu\u1ea7n th\xf4i."}),"\n",(0,c.jsx)(t.p,{children:"B\xe2y gi\u1edd m\xecnh s\u1eafp \u0111\u01b0\u1ee3c nh\u01b0 th\u1ebf r\u1ed3i."}),"\n",(0,c.jsx)(t.p,{children:"C\u1ee9 ti\u1ebfp t\u1ee5c n\xf3i ra nh\u1eefng \u0111i\u1ec1u m\xecnh mu\u1ed1n v\xe0 lao \u0111\u1ed9ng ti\u1ebfp th\xf4i."}),"\n",(0,c.jsx)(t.p,{children:"C\u1ea3m gi\xe1c m\xecnh v\u1eabn c\xf3 th\u1eddi gian \u0111\u1ec3 ch\u01a1i ngu m\xe0 kh\xf4ng ti\u1ebfc trong cu\u1ed9c \u0111\u1eddi n\xe0y. Th\u1eadt l\xe0 may m\u1eafn \ud83e\udd79."})]})}function l(n={}){const{wrapper:t}={...(0,g.R)(),...n.components};return t?(0,c.jsx)(t,{...n,children:(0,c.jsx)(r,{...n})}):r(n)}}}]);